-- 053_company_round_type_taxonomy.sql — seed company_interview_profiles with the
-- technical round_type for 48 high-frequency target companies (+2 name aliases).
--
-- Purpose: lets the Technical workspace + coach calibrate DSA emphasis per company.
--   Each row carries a single `technical-1` process_shape entry whose `round_type`
--   the admin-api + coach resolvers read (first stage starting with 'technical').
--   round_type taxonomy: dsa | practical | take-home | system-design | mixed.
--
-- Provenance: every row's `source` cites a 2024-2026 interview report (Glassdoor,
--   interviewing.io, eng blogs, InterviewQuery, Exponent, TechPrep, Taro, IGotAnOffer,
--   prepfully, vendor handbooks). Confidence (high|medium|low) is recorded both in the
--   row `source` text and in each process_shape entry's `confidence` field — honest:
--   low-confidence rows are inferred, not asserted. Retrieved 2026-06-02.
--
-- Honesty notes:
--   * microsoft: no reliable 2024+ source found in research — seeded 'dsa' (the long-
--     standing default) at confidence 'low', flagged inferred. Safe-mode default is 'dsa'
--     anyway, so a wrong guess here does not over-hide DSA.
--   * Amazon + Stripe are intentionally NOT touched here — migration 052 owns their
--     richer 3-stage process_shape. Re-running 053 will not clobber them.
--   * Aliases (square -> Block, mistralai -> Mistral) cover the two dual-name companies
--     so normalizeCompanyKey() hits regardless of which name a user typed.
--
-- Idempotent: INSERT ... ON CONFLICT (company_key) DO UPDATE — safe to re-run.
BEGIN;

ON CONFLICT (company_key) DO UPDATE SET
  display_name  = EXCLUDED.display_name,
  company_type  = EXCLUDED.company_type,
  process_shape = EXCLUDED.process_shape,
  source        = EXCLUDED.source,
  as_of         = EXCLUDED.as_of;

COMMIT;
